using static StrataLint.Scribe.DefinitionDsl;
using static StrataLint.Scribe.FormulaDsl;
using F = StrataLint.Scribe.FormulaDsl;
namespace StrataLint.Scribe.Blueprint.D5.S3.Quantum.Fibers;
internal sealed class OriginalDownstreamOutputDocument : IScribeDocumentDefinition
{
    public DocumentDefinition Create() => DocumentDefinition.Create(ScribeNode.Create(
        "Common realized downstream actions on the actual complete original quantum output.",
        H("The retained joint cq output and common downstream execution"), Blocks(
            Paragraph(Text("Fix c<1/2, 0<a<c, a finite horizon T>=0 and two original controls (k,chi),(l,psi) on the same base (c,c,1-2c). Both original regularity alternatives, all real phase lifts and signed winding sectors remain in scope. For any complete complex Hilbert reference H and any common positive joint trace-class rho on Blocks(Fin5,H), output packs the literal terminalOutput and all five phasedFailure densities on the original absorbing Blocks(Fin6,H) carrier, with the exact record measure volume restricted to (0,T]. No normalization, separability or finite-rank assumption is used.")),
            Paragraph(Text("Native mode balance applied through height_control proves coefficient integrability for every original control. The original phasedFailure_eq identifies each density with modeCoefficient_i(t) times the same fixed positive absorbing embedding of rho_ii. The actual paired difference therefore has scalar coefficients h_i=modeCoefficient_i(k)-modeCoefficient_i(l) multiplying the same positive operator blocks. RecordedOutput.fixed_block_decomposition applies to this input difference; it imposes no fixed-block restriction on the downstream result. The terminal difference is Hermitian because both actual Kraus congruences are positive.")),
            Entry("actual-distance", "output_distance", "The complete output distance is the cq norm", Distance(),
                "For every such pair and positive joint input, norm(output(k,chi)-output(l,psi))/2 equals the existing completeDistance exactly. The additive WithLp/PiLp norms give the terminal trace norm plus the sum over all five modes of the integral of the density difference trace norm. Integrable.toL1 and its almost-everywhere representatives justify the equality before integration. Signed densities are not integrated before taking norms. At T=0 the record measure is zero, so the same statement includes the zero horizon."),
            Entry("common-execution", "downstream_distance_le", "Common lawful realized executions cannot increase this distance", Downstream(),
                "A Target carries the actual target positive cone predicate, a continuous real-linear mass, norm=mass on positive outputs, and the exact equality of its declared complete distance with half the norm of a difference. A Realization is indexed by an independently specified run(program,context,q) and an independent allowed(program,context) predicate. It supplies the permission proof, one real-linear action, agreement of that action with run on every joint input, positivity on the entire joint cone and mass nonincrease on that cone. The same program and the same Context, containing acquired-record policy, references, permissions and external inputs, are used in both runs. The theorem derives target.distance(run(output(k)),run(output(l)))<=completeDistance. It assumes neither contraction nor an operator norm bound. The map laws are applied to both constructed positive norming parts, not just the two normalized instrument outputs."),
            Entry("uniform-common-execution", "downstream_operational_bound", "The uniform downstream IS.27 bound", Uniform(),
                "Assume in addition k(0)=l(0)=a. For every normalized joint input and arbitrary unchanged complete complex Hilbert reference, supply a target and an actual common execution realization of the same program and context. The supremum of these downstream complete distances is at most kappa+(max_i b_i)/2, with the exact krausError and densityError of IS.27. Each downstream distance is bounded by its corresponding completeDistance. Native boundedness of the original input set justifies comparison with its supremum, and complete_operational_bound then supplies IS.27 directly. A protocol family independent of rho is a special case; the same-input comparison always uses one common action in both experiments."),
            Paragraph(Text("This semantic interface permits record-conditioned adaptive policies with different observed branches; no finite-round, finite-outcome, matrix or reference-dimension restriction occurs. It does not construct arbitrary program semantics. A separately specified class of legal programs is covered only when its actual executions have these witnesses. Complete positivity, normality, countable additivity, reference amplification and record measurability must be justified by each actual realization where applicable; generic positivity grants no access permission. Limiting procedures require their actual existence and convergence evidence.")),
            Paragraph(Text("Mass preservation is a special case of mass nonincrease. A trace-nonincreasing branch is compared with its actual unnormalized output; a complete output retains every required failure/abort successor. No normalized-postselection claim follows. A fixed independent common external state requires its actual positive mass-preserving preparation as part of run. A correlated external system belongs in the same initial joint input, possibly absorbed into the arbitrary retained reference. Equal external marginals do not establish the required joint comparison.")),
            Paragraph(Text("IS.27 bounds complete-output error by terminal Kraus error plus half the largest mode loss-density error. IS.28/29 and complete-output convergence provide sufficient data for those errors. The common realized downstream action preserves these upper bounds. The existing concatenate_original supplies legal original continuation at the same base and matching current height for every finite duration including zero, with the literal prefix and relatively translated real-phase tail. Its original regularity and winding scope is unchanged; it supplies no post-failure positive-carrier restart. No omitted old programme fields, different guards or earlier quantum cuts become accessible. No relative phase waveform, real-lift anchor, calibrated phase acquisition or noisy phase unwrapping is obtained. Unknown past beta,m are not passed to the controller. An acquisition service or complete internal observer still needs its own joint legality, failure and update proof; this is an independent limitation and no construction of such a service is promised.")))));
    private static DocumentBlock Entry(string id,string name,string title,Formula formula,string text) =>
        Describe.Lean(DescribeId.Create(id),DeclarationHandle.Create("D5/S3/Quantum/Fibers/OriginalDownstreamOutput."+name),
            H(title),StatementSource.FromAuthor(Disp(formula)),AssessedProvenance.FromRepo(),
            Blocks(Paragraph(Text(text))),DescribeRole.Theorem);
    private static Formula I(string n)=>F.Id(n);
    private static Formula C(string n,params Formula[] xs)=>new Formula.Apply(I(n),[..xs]);
    private static Formula E(Formula x,Formula y)=>new Formula.Relation(x,FormulaRelationOperator.Equal,y);
    private static Formula L(Formula x,Formula y)=>new Formula.Relation(x,FormulaRelationOperator.LessThanOrEqual,y);
    private static Formula A(Formula x,Formula y)=>new Formula.Logic(x,FormulaLogicOperator.And,y);
    private static Formula P(Formula x,Formula y)=>new Formula.Logic(x,FormulaLogicOperator.Implies,y);
    private static Formula.BoundVariable V(string n,string t)=>new(FormulaIdentifier.Create(n),I(t));
    private static Formula Q(Formula body,params Formula.BoundVariable[] vs)=>new Formula.BindMany(FormulaQuantifier.ForAll,[..vs],body);
    private static Formula Common()=>A(C("cLessHalf",I("c")),A(C("initialInterior",I("a"),I("c")),
        A(C("OriginalControl",I("c"),I("T"),I("k"),I("chi")),A(C("OriginalControl",I("c"),I("T"),I("l"),I("psi")),C("Positive",I("rho"))))));
    private static Formula Out(string k,string chi)=>C("output",I("c"),I("a"),I("T"),I(k),I(chi),I("rho"));
    private static Formula OriginalDistance()=>C("completeDistance",I("c"),I("a"),I("T"),I("k"),I("chi"),I("l"),I("psi"),I("rho"));
    private static Formula.BoundVariable[] Inputs()=>[V("H","CompleteComplexHilbertSpace"),V("c","Real"),V("a","Real"),V("T","Real"),V("k","RealPath"),V("chi","RealPath"),V("l","RealPath"),V("psi","RealPath"),V("rho","JointTraceClass")];
    private static Formula Distance()=>Q(P(Common(),E(C("halfNormDifference",Out("k","chi"),Out("l","psi")),OriginalDistance())),Inputs());
    private static Formula Uniform()=>Q(P(A(C("CommonOriginalPairWithInitialHeight",I("c"),I("a"),I("T"),I("k"),I("chi"),I("l"),I("psi")),
        C("AllJointInputRealizations",I("target"),I("run"),I("allowed"),I("program"),I("context"),I("R"))),
        L(C("sSup",C("ActualDownstreamDistances",I("target"),I("run"),I("program"),I("context"))),
            C("add",C("krausError",I("c"),I("a"),I("T"),I("k"),I("chi"),I("l"),I("psi")),C("halfMaxDensityError",I("c"),I("a"),I("T"),I("k"),I("l"))))),
        V("c","Real"),V("a","Real"),V("T","Real"),V("k","RealPath"),V("chi","RealPath"),V("l","RealPath"),V("psi","RealPath"),
        V("W","JointInputIndexedRealSeminormedSpaces"),V("target","TargetFamily"),V("run","ActualJointExecutionFamily"),V("allowed","IndependentLegalityPredicate"),V("program","Program"),V("context","CommonPolicyReferencePermissionExternalInputs"),V("R","RealizationFamily"));
    private static Formula Downstream()=>Q(P(A(Common(),C("Realization",I("target"),I("run"),I("allowed"),I("program"),I("context"),I("R"))),
        L(C("targetDistance",C("run",I("program"),I("context"),Out("k","chi")),C("run",I("program"),I("context"),Out("l","psi"))),OriginalDistance())),
        [..Inputs(),V("W","RealSeminormedSpace"),V("target","PositiveNormMassDistanceTarget"),V("run","ActualJointExecution"),V("allowed","IndependentLegalityPredicate"),V("program","Program"),V("context","CommonPolicyReferencePermissionExternalInputs"),V("R","RealizationWitness")]);
}
